export function readPublishedGalaxyNumeric(scope,kind,start='',end=''){
  const groups=Object.hasOwn(GROUPS,scope)?GROUPS[scope]:null;
  if(!groups)return null;
  const earliest=groups.find(([, ,statics])=>statics>0)?.[0]||'';
  if(kind==='earliest')return earliest;
  const inRange=day=>(!start||day>=start)&&(!end||day<=end);
  if(kind==='totals'){
    const counts=new Map();
    for(const [day,site,statics] of groups){
      if(statics>0&&inRange(day))counts.set(site,(counts.get(site)||0)+statics);
    }
    return [...counts].sort(([a],[b])=>a.localeCompare(b)).map(([category,item_count])=>({kind:'source',category,item_count}));
  }
  if(!['culture_density','daily','overview'].includes(kind))return null;
  if(kind==='culture_density'){
    return groups.filter(([day,, ,culture])=>culture>0&&inRange(day)).map(([day,site,,item_count])=>({day,site,item_count}));
  }
  const rows=[],totalByDay=new Map();
  for(const [day,site,statics] of groups){
    if(statics<1||!inRange(day))continue;
    rows.push({day,kind:'source',category:site,item_count:statics});
    totalByDay.set(day,(totalByDay.get(day)||0)+statics);
  }
  for(const [day,item_count] of totalByDay)rows.push({day,kind:'total',category:'文字作品',item_count});
  rows.sort((a,b)=>a.day.localeCompare(b.day)||a.kind.localeCompare(b.kind));
  return kind==='overview'?{earliest,rows,categories:[],aliases:[]}:rows;
}
